const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Petén department in Guatemala (approximate bounding box)
  var geometry = ee.Geometry.Polygon([[
    [-92.0, 17.0],
    [-89.0, 17.0],
    [-89.0, 16.0],
    [-92.0, 16.0]
  ]], null, false);

  var start2001 = '2001-01-01';
  var end2001 = '2001-12-31';
  var start2023 = '2023-01-01';
  var end2023 = '2023-12-31';

  // 2. Data Acquisition - Using Hansen Forest Cover dataset
  var gfc2000 = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Get tree cover in 2000 (baseline for 2001)
  var treeCover2000 = gfc2000.select('treecover2000');

  // Loss up to 2001 (lossyear values 1 for 2001 loss)
  var loss2001 = gfc2000.select('lossyear').eq(1);

  // Loss up to 2023 (all loss years 2001-2023)
  var loss2023 = gfc2000.select('loss').eq(1);

  // Forest cover calculations
  var forest2001 = treeCover2000.multiply(loss2001.not());
  var forest2023 = treeCover2000.multiply(loss2023.not());

  // 3. Check for valid pixels
  var stats2001 = forest2001.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  var stats2023 = forest2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  var count2001 = stats2001.get('treecover2000').getInfo();
  var count2023 = stats2023.get('treecover2000').getInfo();

  if (count2001 === 0 || count2023 === 0) {
    print("No valid pixels after processing.");
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - total forest cover
  var total2001 = forest2001.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('treecover2000').getInfo();

  var total2023 = forest2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('treecover2000').getInfo();

  // 5. Validation & Final Answer
  print("2001 Forest Cover: " + total2001.toFixed(0));
  print("2023 Forest Cover: " + total2023.toFixed(0));
  print("Change: " + (total2023 - total2001).toFixed(0));

  if (total2001 === null || total2023 === null || 
      isNaN(total2001) || isNaN(total2023) ||
      total2001 < 0 || total2023 < 0) {
    print("<answer>C3</answer>");
  } else if (total2023 < total2001) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
